-- 183: Original BrillaPrep WASSCE BrillaPrep transitional Woodwork beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_183_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_183_guard;
INSERT INTO _migration_183_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_016' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_4' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which joint is well suited to connecting a rail to a stile in a framed door?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A simple end-grain butt joint without reinforcement","B. A sheet-metal lap seam","C. A soldered scarf joint","D. A mortise-and-tenon joint"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The tenon provides long-grain glue area and mechanical shoulders while the mortise locates it within the stile. Therefore the correct answer is D: A mortise-and-tenon joint.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_016' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_183_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_017' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_4' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are dovetail joints effective at the corners of a drawer?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Their interlocking shape resists withdrawal under pulling load","B. They depend only on end-grain glue strength","C. They allow the front to slide off freely","D. They require no accurate fitting"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The tails and pins mechanically lock in the direction that drawer fronts are commonly pulled, with adhesive stabilising the assembly. Therefore the correct answer is A: Their interlocking shape resists withdrawal under pulling load.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_017' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_183_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_018' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_4' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a haunch on a tenon used near the end of a grooved stile?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Remove all support from the tenon shoulder","B. Fill the groove and resist twisting while preserving material at the stile end","C. Create a through hole for a bolt only","D. Make the groove continue outside the joint"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The haunch closes the groove and improves alignment without requiring a full-width mortise that would weaken the end of the stile. Therefore the correct answer is B: Fill the groove and resist twisting while preserving material at the stile end.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_018' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_183_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_019' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_4' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should the shoulders of a tenon seat firmly against the mating member?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Keep the rail separated by an open gap","B. Transfer load only through exposed end grain","C. Provide accurate location and help resist racking","D. Prevent the tenon entering the mortise"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Well-fitted shoulders establish the frame geometry and increase bearing against forces that would distort the joint. Therefore the correct answer is C: Provide accurate location and help resist racking.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_019' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_183_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_020' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_4' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which joint is appropriate for lengthening two timber members while maintaining alignment?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An unsupported square butt with no fastener","B. A housing joint across board width","C. A bridle joint used only at a corner","D. A properly designed scarf joint"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A scarf provides overlapping or interlocking long surfaces that transfer force and maintain alignment better than a plain end butt. Therefore the correct answer is D: A properly designed scarf joint.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_020' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
